sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.field-widget {
    text-align: center;
    padding: 20px;
    background-color: #f4f4f4;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
}
h2 {
    font-size: 1.5em;
    margin-bottom: 10px;
}
p {
    font-size: 2em;
    color: red; /* Set the field value text color to red */
    font-weight: bold; /* Optional: make it bold for emphasis */
}

sp_widget.script:
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */
  // Retrieve the specific field value
(function() {
    // Replace 'your_table' and 'sys_id_of_record' with actual table and record sys_id
    var record = new GlideRecord('x_1468042_lva_loaner_vehicle_catalog'); 
    if (record.get('ba3c27a083931a10b1d19bc6feaad3d4')) {
        data.fieldValue = record.getValue('mpg'); // Replace 'your_field_name' with the field
    } else {
        data.fieldValue = "Record not found.";
    }
})();
